94:function csvField(value: string): string {
99:const EXPORT_CELLS = [
  }

  /** How far the person's figures (their due-total before the cap plus their cut total) add up above the cap, in
   *  whole cents; 0 when they do not, there is no cap, or they have no due-total (none, or nothing due). */
  protected excessOf(personId: number): number {
    const sum = this.uncappedDueByPerson().get(personId) ?? null;
    const cap = this.capCents();
    return sum === null || sum === 0 || cap === null ? 0 : Math.max(0, sum + this.cutOf(personId) - cap);
  }

  /** Download the people as CSV, in list order, retired people included. */
  protected exportCsv(): void {
    const lines = [
      ['name', 'grade', 'retired-from', 'due-total'],
      ...this.people().map((p) => [p.name, this.gradeToday(p), p.retiredFrom ?? '', this.dueOf(p)]),
    ].map((fields) => fields.map(csvField).join(',') + '\n');
    this.download(lines, 'people');
  }

  /** Download the claims as CSV: people in list order, retired people included, each person's claims oldest
   *  first, with the figures as the claims list shows them. */
  protected exportClaims(): void {
    const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
    const lines = [
      ['person', 'number', 'date', 'amount', 'due', 'status', 'period'],
      ...this.people().flatMap((p) => [...this.claimsOf(p.id)].reverse().map((c) => {
        const due = this.claimDue(p, c, dueTerms);
        return [p.name, c.number ?? '', c.date, c.amount,
          due === null ? NOT_AVAILABLE : money(due), c.status, periodOn(this.periods.list(), c.dueBy)?.name ?? ''];
      })),
    ].map((fields) => fields.map(csvField).join(',') + '\n');
    this.download(lines, 'claims');
  }

  /** Download the period figures as CSV: people in list order, retired people included, each person's periods in
   *  the order added, with the due-total and carried figure as the person's row shows them. */
  protected exportPeriods(): void {
    const periods = [...this.periods.list()].sort((a, b) => a.id - b.id);
    const lines = [
      ['person', 'period', 'figure', 'carried'],
      ...this.people().flatMap((p) => periods.map((pd) =>
        [p.name, pd.name, this.periodDueOf(p.id, pd.id), this.periodCarriedOf(p.id, pd.id)])),
    ].map((fields) => fields.map(csvField).join(',') + '\n');
    this.download(lines, 'periods');
  }

  /** Download the person's statement as CSV: each claim of theirs their last statement binds, oldest first, with
   *  the figure it is bound to as the claim shows it. */
  protected exportStatement(p: PersonView): void {
    const lines = [
      ['number', 'date', 'amount', 'figure', 'status'],
      ...[...this.claimsOf(p.id)].reverse().filter((c) => c.stated)
        .map((c) => [c.number ?? '', c.date, c.amount, c.statedDue ?? NOT_AVAILABLE, c.status]),
    ].map((fields) => fields.map(csvField).join(',') + '\n');
    this.download(lines, 'statement-' + p.id);
  }

  private download(lines: string[], what: string): void {
    const url = URL.createObjectURL(new Blob(lines, { type: 'text/csv' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = what + '-' + (this.sheets.current()?.id ?? 'sheet') + '.csv';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url));
